WITH gaps AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY event_type ORDER BY event_time ASC, id ASC) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY event_type ORDER BY event_time ASC, id ASC) + INTERVAL '90' DAY THEN 1 ELSE 0 END AS is_new_session FROM web_events), sessionized AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY event_type ORDER BY event_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM gaps) SELECT id, event_type, burst_id, CASE WHEN event_type RLIKE '^(click|add_to_cart)$' THEN 'GROUP_A' ELSE 'GROUP_B' END AS event_type_zone FROM sessionized;
